import {esc,cash,icon,pageHead,progress as progressBar} from './ui.js';
import qrcode from './vendor/qrcode.js';

const list=value=>Array.isArray(value)?value:[];
const clone=value=>structuredClone(value);
const limit=(value,max=160)=>String(value??'').slice(0,max);
const uid=()=>globalThis.crypto?.randomUUID?.()||'rewards-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);
const truth=value=>value===true||value==='on'||value==='true';
const date=value=>{const d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleDateString('en-GH',{day:'numeric',month:'short',year:'numeric',timeZone:'Africa/Accra'}):'Not recorded';};
const palette=value=>/^#[a-f0-9]{6}$/i.test(value||'')?value:'#d4f65a';
function ink(value){const rgb=palette(value).slice(1).match(/../g).map(n=>{const c=parseInt(n,16)/255;return c<=.04045?c/12.92:((c+.055)/1.055)**2.4;});return rgb[0]*.2126+rgb[1]*.7152+rgb[2]*.0722>.18?'#20211c':'#ffffff';}
const button=(text,action,{style='secondary',disabled=false,extra=''}={})=>`<button type="button" class="button ${style}" data-rewards-action="${action}" ${disabled?'disabled':''} ${extra}>${text}</button>`;
const eventNames={earn:'Purchase counted','member-enrolled':'Membership created','reward-earned':'Reward earned','reward-redeemed':'Reward used','reward-expired':'Reward expired','refund-adjustment':'Returned purchase adjustment','reward-revoked':'Reward adjusted','progress-adjusted':'Progress corrected','member-linked':'Membership linked','item-fulfilled':'Item collected','earning-paused':'Earning paused'};
const rewardState={available:'Ready to use',held:'Reserved for a payment',redeemed:'Used',expired:'Expired',revoked:'Adjusted'};
const definitive=result=>result?.noMutation===true||result?.definitiveNoMutation===true||['INVALID_INPUT','FORBIDDEN','LOYALTY_CONSENT_REQUIRED','LOYALTY_INVALID','LOYALTY_NOT_CONFIGURED','LOYALTY_PAUSED','LOYALTY_CAPACITY','LOYALTY_RULE_CHANGED','LOYALTY_CLAIM_INVALID','LOYALTY_CLAIM_EXPIRED','LOYALTY_ALREADY_LINKED','LOYALTY_ALREADY_JOINED','LOYALTY_TERMS_CHANGED','LOYALTY_PROGRAMME_UNAVAILABLE','LOYALTY_MEMBERSHIP_UNAVAILABLE','LOYALTY_COLLECTION_UNAVAILABLE','LOYALTY_MEMBER_INACTIVE','PERSONAL_ACCOUNT_REQUIRED','ACCOUNT_CLOSED','REQUEST_PROCESSING'].includes(result?.code);

/** This view owns no money, reward balance or payment authorisation. */
export function createConsumerRewards(config={}) {
 let identity='',generation=0,sequence=0,view=null,status='idle',error='',notice='',busy=false,selected='',context={},form='',pending=null,pendingMemory=null,reentry=false,selectedShop='',claimDraft='',claimProgramme=null,cancelRequest='',programmeUnavailable=false,listeners=new Set();
 const actor=()=>String(config.getUserId?.()||'');
 const scope=()=>String(config.getIdentity?.()||'');
 const signedIn=()=>config.isAuthenticated?.()===true&&!!actor();
 const readOnly=()=>config.isReadOnly?.()===true;
 const readOnlyMessage='Your account is closed. Existing rewards are available to read; membership and payment changes are unavailable.';
 const storage=()=>{try{return config.storage===undefined?globalThis.sessionStorage:config.storage;}catch{return null;}};
 const storageKey=user=>`lumo-consumer-rewards-pending-v1:${encodeURIComponent(user||actor())}`;
 let storageOwner='';
 function notify(){config.onChange?.();for(const listener of [...listeners])listener();}
 function resetPrivate(){generation++;sequence++;view=null;status='idle';error='';notice='';busy=false;selected='';context={};form='';pending=null;pendingMemory=null;reentry=false;selectedShop='';claimDraft='';claimProgramme=null;cancelRequest='';programmeUnavailable=false;}
 function ensure(){const next=scope();if(next!==identity){resetPrivate();identity=next;storageOwner=actor();if(signedIn())try{const saved=JSON.parse(storage()?.getItem(storageKey())||'null');if(saved&&['join','claim','cancel'].includes(saved.operation)&&/^[A-Za-z0-9_.:-]{10,100}$/.test(saved.attemptId||'')){pending={operation:saved.operation,attemptId:saved.attemptId,...(typeof saved.shopId==='string'?{shopId:saved.shopId}:{}),...(saved.operation==='cancel'&&typeof saved.membershipId==='string'&&typeof saved.requestId==='string'?{membershipId:saved.membershipId,requestId:saved.requestId}:{})};if(saved.operation==='cancel')selected=saved.membershipId;}}catch{}}}
 function remember(value){pending=value;if(!value)pendingMemory=null;try{if(value)storage()?.setItem(storageKey(),JSON.stringify({operation:value.operation,attemptId:value.attemptId,...(value.shopId?{shopId:value.shopId}:{}),...(value.operation==='cancel'?{membershipId:value.membershipId,requestId:value.requestId}:{})}));else storage()?.removeItem(storageKey());}catch{}}
 const current=(epoch,owner)=>{ensure();return epoch===generation&&owner===identity&&signedIn();};
 function install(result){if(!result?.loyalty||typeof result.loyalty!=='object')throw Error('Your rewards could not be read. Refresh to check the current records.');view=clone(result.loyalty);if(view.membership){selected=view.membership.id;form='';}if(selected&&!view.membership&&!list(view.memberships).some(m=>m.id===selected))selected='';const member=membership();if(member&&!list(member.shops).some(s=>s.id===selectedShop))selectedShop=list(member.shops).find(s=>s.published&&s.accepting)?.id||list(member.shops)[0]?.id||'';status='loaded';programmeUnavailable=!!context.shopId&&!view.programme&&!view.membership;}
 const membership=()=>view?.membership?.id===selected?view.membership:list(view?.memberships).find(m=>m.id===selected)||null;
 async function call(operation,payload={},options={}){if(typeof config.api!=='function')throw Error('Reconnect to check your merchant rewards.');return config.api(operation,payload,options);}
 async function refresh({membershipId,shopId,quiet=false}={}){ensure();if(!signedIn()||busy&&!quiet)return false;const epoch=generation,owner=identity,request=++sequence;const chosen=membershipId||selected,shop=shopId||context.shopId;status='loading';if(!quiet)error='';notify();try{const result=await call(chosen?'detail':shop?'programme':'list',chosen?{membershipId:chosen}:shop?{shopId:shop}:{});if(!current(epoch,owner)||request!==sequence)return false;if(!result?.ok){if(shop&&!chosen&&['LOYALTY_NOT_CONFIGURED','LOYALTY_PROGRAMME_UNAVAILABLE','SHOP_UNAVAILABLE','LOYALTY_SHOP_UNAVAILABLE'].includes(result?.code)){view={memberships:[],membership:null,programme:null};programmeUnavailable=true;status='loaded';error='';return true;}throw Error(result?.message||result?.error||'Your rewards could not refresh. Reconnect and try again.');}install(result);if(context.shopId&&view.programme?.membershipId&&!view.membership){selected=view.programme.membershipId;return await refresh({membershipId:selected,quiet:true});}return true;}catch(failure){if(current(epoch,owner)&&request===sequence){status='error';error=failure.message||'Your rewards could not refresh. Reconnect and try again.';}return false;}finally{if(current(epoch,owner)&&request===sequence)notify();}}
 async function submitMutation(operation,payload){ensure();if(!signedIn()||busy||pending&&!reentry)return false;if(readOnly()){error=readOnlyMessage;notify();return false;}const epoch=generation,owner=identity;const attemptId=pending?.attemptId||uid();if(pending&&pending.operation!==operation)return false;pendingMemory={operation,payload:clone(payload),attemptId};remember({operation,attemptId,shopId:payload.shopId,...(operation==='cancel'?{membershipId:payload.membershipId,requestId:payload.requestId}:{})});busy=true;reentry=false;error='';notice='';notify();try{const result=await call(operation,payload,{attemptId});if(!current(epoch,owner))return false;if(!result?.ok){if(definitive(result)){remember(null);error=result?.message||result?.error||'This membership change was not saved. Check the details and try again.';}else error=result?.message||result?.error||'The result is still unknown. Check this original reference before trying again.';return false;}install(result);remember(null);form='';notice=operation==='cancel'?'The original payment request was cancelled. Your current rewards are shown below.':operation==='claim'?'Your existing membership is linked.':'You’re in. Your next qualifying purchase can count.';claimDraft='';claimProgramme=null;cancelRequest='';const id=result.entity?.membershipId||result.entity?.id||view.membership?.id;if(id&&!membership()){selected=id;await refresh({membershipId:id,quiet:true});}return true;}catch(failure){if(current(epoch,owner)){if(definitive(failure))remember(null);error=failure.message||'The result could not be confirmed. Check this original reference.';}return false;}finally{if(current(epoch,owner)){busy=false;notify();}}}
 async function recover(){ensure();if(!signedIn()||busy||!pending)return false;const epoch=generation,owner=identity,saved=clone(pending);busy=true;error='';notice='';notify();try{const result=await call('recover',{attemptId:saved.attemptId});if(!current(epoch,owner))return false;if(!result?.ok){error=result?.message||result?.error||'The original request could not be checked. Reconnect and try again.';return false;}const receipt=result.loyalty?.mutationReceipt||result.mutationReceipt;if(receipt?.found===true&&(receipt.operation!==saved.operation||saved.operation==='cancel'&&(receipt.entity?.membershipId!==saved.membershipId||receipt.entity?.requestId!==saved.requestId)))throw Error('The returned receipt does not match your original request. Keep this reference and check again.');install(result);if(receipt?.found===true){remember(null);form='';notice='Your original membership change was confirmed.';const id=receipt.entity?.membershipId||receipt.entity?.id||view.membership?.id;if(id){selected=id;await refresh({membershipId:id,quiet:true});}return true;}if(receipt?.found===false){if(readOnly()){notice='This original reference has no saved outcome yet. Your closed account is available to read; no retry was sent.';return false;}if(saved.operation==='cancel'&&!pendingMemory&&saved.membershipId&&saved.requestId){busy=false;reentry=true;return await submitMutation('cancel',{membershipId:saved.membershipId,requestId:saved.requestId});}if(pendingMemory){const retry=clone(pendingMemory);busy=false;reentry=true;return await submitMutation(retry.operation,retry.payload);}reentry=true;form=saved.operation;notice='This reference has no saved outcome yet. Enter the same details to retry the original request.';if(saved.shopId){context.shopId=saved.shopId;await refresh({shopId:saved.shopId,quiet:true});}return false;}error='The service did not confirm whether the original request was saved. Keep this reference and check again.';return false;}catch(failure){if(current(epoch,owner))error=failure.message||'The original request could not be checked.';return false;}finally{if(current(epoch,owner)){busy=false;notify();}}}
 function open(next={}){ensure();const cleaned={...(next.shopId?{shopId:limit(next.shopId,100)}:{}),...(next.businessId?{businessId:limit(next.businessId,100)}:{})};if(JSON.stringify(cleaned)!==JSON.stringify(context)){generation++;sequence++;view=null;status='idle';error='';notice='';form='';selected='';selectedShop='';claimDraft='';claimProgramme=null;cancelRequest='';programmeUnavailable=false;context=cleaned;}if(next.membershipId)selected=limit(next.membershipId,100);}
 function card(member,{compact=false}={}){const p=member.programme||{},target=Number(member.target)||0,rawValue=Number(member.progress)||0,value=Math.max(0,rawValue),spend=member.earning==='spend';const amount=spend?`${cash(rawValue)} of ${cash(target)}`:`${rawValue} of ${target} stamps`,ready=list(member.rewards).filter(r=>r.state==='available'&&(!r.expiresAt||Date.parse(r.expiresAt)>(config.now?.()??Date.now()))).length;return `<${compact?'button':'section'} ${compact?`type="button" data-rewards-action="member" data-membership-id="${esc(member.id)}"`:''} class="rewards-card ${compact?'rewards-card--compact':''}" style="--rewards-colour:${palette(p.colour)};--rewards-ink:${ink(p.colour)}" aria-label="${esc(member.merchantName||'Merchant')} loyalty card"><span class="rewards-business">${esc(member.merchantName||'Your merchant')}</span><h2>${esc(p.name||'Your rewards')}</h2><strong class="rewards-progress-copy">${esc(amount)}</strong>${progressBar(value,target,'rewards-progress')}<p>${ready?`${ready} ${ready===1?'reward':'rewards'} ready`:'Your next reward is taking shape.'}${member.active===false?' · Membership inactive':''}</p>${rawValue<0?'<p class="rewards-progress-adjusted">A return adjusted your programme progress. The shop team can review this with you.</p>':''}${compact?`<span class="rewards-card-open">View card & rewards ${icon('chevron',16)}</span>`:''}</${compact?'button':'section'}>`;}
 function rulesView(rules,terms){return `<div class="rewards-terms"><h3>How it works</h3><p>${esc(terms||'Ask the merchant for this programme’s terms before joining.')}</p>${!terms&&rules?.onePerDay&&rules.earning==='visits'?'<p>At most one qualifying visit per day across participating shops.</p>':''}<p>Rewards belong to this merchant’s programme and cannot be added to your money balance.</p></div>`;}
 function codeView(member){let qr='';if(typeof member.code==='string'&&member.code.length<=120)try{const code=qrcode(0,'M');code.addData(member.code,'Byte');code.make();qr=code.createSvgTag({cellSize:4,margin:16,scalable:true,title:'Your merchant membership card',alt:'Show this code to the merchant to find this membership.'});}catch{}return `<section class="rewards-code-panel"><h3>Your membership card</h3>${qr?`<div class="rewards-code">${qr}</div>`:''}<strong class="rewards-member-code">${esc(member.code||'Code unavailable')}</strong><p>This identifies your membership at ${esc(member.merchantName||'this merchant')}. It is not a payment QR or an account-linking code.</p>${member.code?button('Copy membership code','copy-code'):''}</section>`;}
 function shopsView(shops){return `<section class="rewards-panel"><h3>Participating shops</h3>${list(shops).map(s=>`<div class="rewards-shop"><span>${esc(s.name||'Shop')}</span><small>${s.published===true?(s.accepting===true?'Accepting payments':'Payments paused'):'Currently unavailable'}</small></div>`).join('')||'<p class="muted">Ask the merchant which shop can honour your reward.</p>'}</section>`;}
 function rewardsView(member){const rewards=list(member.rewards),shops=list(member.shops),usableShops=shops.filter(s=>s.published===true&&s.accepting===true);return `<section class="rewards-panel"><h3>Your rewards</h3>${rewards.length?rewards.map(r=>{const expired=r.expiresAt&&Date.parse(r.expiresAt)<=(config.now?.()??Date.now()),available=r.state==='available'&&!expired&&member.active!==false&&!readOnly();return `<article class="rewards-earned"><div><small class="rewards-state">${esc(expired&&r.state==='available'?'Expired':rewardState[r.state]||'Unavailable')}</small><h4>${esc(r.name||'Merchant reward')}</h4><p>${r.type==='discount'?`${cash(r.value)} off${r.minimumSpend?` · Minimum purchase ${cash(r.minimumSpend)}`:''}`:'Collect this item from the shop team.'}</p><p>${r.expiresAt?'Use by '+esc(date(r.expiresAt)):'Ask the shop about expiry.'}</p></div>${available?button(r.type==='item'?'Show my card':'Use reward',r.type==='item'?'show-code':'use',{disabled:busy||!!pending||r.type==='discount'&&!usableShops.length,extra:`data-reward-id="${esc(r.id)}"`}):''}</article>`;}).join(''):'<p class="muted">Earned rewards will appear here after qualifying confirmed purchases.</p>'}${usableShops.length>1?`<label class="field"><span>Shop for your next payment</span><select class="input" name="rewardsShop">${usableShops.map(s=>`<option value="${esc(s.id)}" ${s.id===selectedShop?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>`:''}<p class="rewards-note">Item rewards are handed over by the merchant. The shop team confirms fulfilment.</p></section>`;}
 function memberView(member){return `<div class="rewards-detail-top">${button('All my rewards','all')}<span class="rewards-state">Rules v${esc(member.ruleVersion||'1')}${member.programme?.status==='paused'?' · New earning paused':''}</span></div>${card(member)}${member.active===false?'<p class="notice">This membership is inactive. Ask the merchant to review it.</p>':''}${collectionsView(member)}${rewardsView(member)}${codeView(member)}${list(member.shops).some(s=>s.published===true&&s.accepting===true)?button('Pay this merchant','pay',{style:'primary',disabled:busy||!!pending||member.active===false||readOnly()}):''}${rulesView(member.rules,member.terms)}${shopsView(member.shops)}<section class="rewards-panel"><h3>Recent activity</h3>${list(member.history).slice(0,30).map(event=>`<div class="rewards-history"><div><strong>${esc(eventNames[event.type]||'Programme update')}</strong><small>${esc(event.shopName||'This merchant')} · ${esc(date(event.createdAt))}</small></div><span>${Number(event.units)>0?'+':''}${esc(member.earning==='spend'?cash(event.units):Number(event.units)||0)}</span></div>`).join('')||'<p class="muted">Your qualifying purchases and reward updates will appear here.</p>'}</section>`;}
 function consentInputs(join){return `<label class="rewards-consent"><input type="checkbox" name="membershipConsent" required><span>${join?'I have read this programme’s terms and agree to join.':'I agree to link my existing merchant membership to this signed-in Lumo account.'}</span></label><label class="rewards-consent"><input type="checkbox" name="marketingConsent"><span>I would like marketing updates from this merchant. <small>Optional. You can earn rewards without agreeing.</small></span></label>`;}
 function programmeView(program){const p=program.programme||{},completeTerms=!!program.rules&&Number.isInteger(program.ruleVersion)&&program.ruleVersion>0&&typeof program.consentVersion==='string'&&program.consentVersion.length>0&&typeof program.terms==='string'&&program.terms.trim().length>0,canJoin=program.canJoin===true&&completeTerms&&!readOnly();return `<section class="rewards-card rewards-programme" style="--rewards-colour:${palette(p.colour)};--rewards-ink:${ink(p.colour)}"><span class="rewards-business">${esc(program.merchantName||'This merchant')}</span><h2>${esc(p.name||'Merchant rewards')}</h2><p>Your regular purchases can add up to something good.</p></section>${rulesView(program.rules,program.terms)}${shopsView(program.shops)}${canJoin?`<form class="rewards-form" data-rewards-form="join">${consentInputs(true)}<button class="button primary" ${busy||pending&&!reentry||readOnly()?'disabled':''}>${busy?'Joining…':'Join this programme'}</button></form>`:`<p class="notice">${readOnly()?readOnlyMessage:program.membershipId?'You already belong to this programme. Refresh to open your card.':!completeTerms?'Programme terms are unavailable. Refresh before joining.':'This programme is not accepting new members right now.'}</p>`}${button('Link an existing membership instead','claim',{disabled:busy||!!pending&&!reentry||readOnly()})}<p class="rewards-note">Joining shares your Lumo display name with this merchant. Your balance, budgets and other merchants’ memberships stay private.</p>`;}
 function claimView(){const checked=claimProgramme;return `<section class="rewards-panel"><h2>${checked?'Your existing terms.':'Bring your existing card.'}</h2><p>${checked?'Review these pinned programme terms before linking the membership to this Lumo account.':'Ask the shop team for a private, one-time account-linking code. Your printed membership code cannot link an account.'}</p>${checked?`<div class="rewards-claim-checked"><strong>${esc(checked.merchantName||'This merchant')} · ${esc(checked.programme?.name||'Loyalty programme')}</strong><p>Private linking code checked · Rules v${esc(checked.ruleVersion)}</p></div>${rulesView(checked.rules,checked.terms)}<form class="rewards-form" data-rewards-form="claim">${consentInputs(false)}<button class="button primary" ${busy||pending&&!reentry||readOnly()?'disabled':''}>${busy?'Linking…':'Link my membership'}</button></form>${button('Use a different code','claim-reset',{disabled:busy||!!pending&&!reentry||readOnly()})}`:`<form class="rewards-form" data-rewards-form="claim-code"><label class="field"><span>Private account-linking code</span><input class="input" name="claimCode" type="text" maxlength="160" autocomplete="off" autocapitalize="off" spellcheck="false" required></label><button class="button primary" ${busy||pending&&!reentry||readOnly()?'disabled':''}>${busy?'Checking…':'Check linking code'}</button></form>${config.onScanClaim?button('Scan linking code','claim-scan',{disabled:busy||!!pending&&!reentry||readOnly()}):''}`}<p class="rewards-note">The code expires shortly. Your existing progress and rewards stay with the membership. The private code is not saved in your account history or browser storage.</p>${button('Back to rewards','close-form',{disabled:busy})}</section>`;}
 function collectionsView(member){const held=list(member.collections).filter(c=>c.state==='held'&&c.requestId);if(!held.length)return '';return `<section class="rewards-panel"><h3>Original payment requests</h3>${held.map(c=>`<article class="rewards-collection"><h4>${cash(c.amount)} to collect</h4><p>${cash(c.grossAmount)} purchase${c.discount?` · ${cash(c.discount)} reward applied`:''}</p><p>${esc(list(member.shops).find(s=>s.id===c.shopId)?.name||'Participating shop')} · Expires ${esc(date(c.expiresAt))}</p><div class="rewards-collection-actions">${button('Continue original payment','resume',{disabled:busy||!!pending||readOnly(),extra:`data-request-id="${esc(c.requestId)}"`})}${button('Cancel request','cancel-open',{disabled:busy||!!pending||readOnly(),extra:`data-request-id="${esc(c.requestId)}"`})}</div></article>`).join('')}<p class="rewards-note">The reward stays reserved while its original request can still be paid. Check or cancel that request before starting another.</p></section>`;}
 function cancelView(member){const collection=list(member?.collections).find(c=>c.requestId===cancelRequest&&c.state==='held');if(!collection)return '<p class="notice">This request is no longer awaiting payment. Refresh your rewards.</p>';return `<section class="rewards-panel"><h2>Cancel this request?</h2><p>The original ${cash(collection.amount)} payment QR will stop accepting payment. Any reserved reward is checked and released by the service after cancellation is confirmed.</p><form data-rewards-form="cancel" class="rewards-form"><button class="button primary" ${busy||!!pending||readOnly()?'disabled':''}>${busy?'Cancelling…':'Cancel original request'}</button></form>${button('Keep the original request','close-form',{disabled:busy})}</section>`;}
 async function checkClaimCode(raw){ensure();if(!signedIn()||busy||pending&&!reentry)return false;if(readOnly()){error=readOnlyMessage;notify();return false;}const value=String(raw||'').trim();if(!value||value.length>160){error='Enter the private account-linking code from the shop team.';notify();return false;}const epoch=generation,owner=identity;busy=true;error='';notice='';claimDraft=value;claimProgramme=null;form='claim';notify();try{const result=await call('programme',{claimCode:value});if(!current(epoch,owner))return false;if(!result?.ok)throw Error(result?.message||result?.error||'The private linking code could not be checked. Ask the shop for a fresh code.');if(!result.loyalty?.programme?.rules||!result.loyalty.programme.ruleVersion||!result.loyalty.programme.consentVersion||typeof result.loyalty.programme.terms!=='string'||!result.loyalty.programme.terms.trim())throw Error('The service did not return the existing membership terms. Ask for a fresh linking code.');claimProgramme=clone(result.loyalty.programme);return true;}catch(failure){if(current(epoch,owner)){error=failure.message||'The linking code could not be checked.';claimDraft='';claimProgramme=null;}return false;}finally{if(current(epoch,owner)){busy=false;notify();}}}

 function listView(){const members=list(view?.memberships);return `<div class="rewards-intro"><h1>Your regular spots.<br>Your rewards.</h1><p>Cards, progress and earned rewards from the merchants you’ve joined.</p></div>${members.length?`<div class="rewards-card-list">${members.map(m=>card(m,{compact:true})).join('')}</div>`:`<div class="rewards-empty"><span>${icon('spark',34)}</span><h2>A place for your regulars.</h2><p>Open a shop in Campus Pay to see and join its loyalty programme. Already have a card? Ask the shop to link it.</p>${button('Find a campus shop','browse',{style:'primary'})}</div>`}${button('Link an existing membership','claim',{disabled:busy||!!pending&&!reentry||readOnly()})}<p class="rewards-note">Each merchant sets and honours its own rewards. Progress updates from qualifying confirmed purchases and returns.</p>`;}
 function render(){ensure();if(!signedIn())return `<section class="page consumer-rewards" data-consumer-rewards>${pageHead('Your rewards')}<div class="rewards-empty"><h1>Your rewards travel with you.</h1><p>Sign in to your personal Lumo account to join merchant programmes and see your rewards.</p>${button('Sign in','signin',{style:'primary'})}</div></section>`;const member=membership();return `<section class="page consumer-rewards" data-consumer-rewards>${pageHead('Your rewards',{action:button(status==='loading'?'Refreshing…':'Refresh','refresh',{disabled:busy||status==='loading'})})}<div data-rewards-content>${readOnly()?`<p class="notice rewards-readonly" role="status">${esc(readOnlyMessage)}</p>`:''}${pending?`<div class="notice rewards-pending" role="status"><strong>Let’s check your original request.</strong><p>Its outcome is not confirmed. Keep this reference before making another membership change.</p><code>${esc(pending.attemptId)}</code>${button(busy?'Checking…':'Check original request','recover',{disabled:busy})}</div>`:''}${error?`<p class="notice rewards-error" role="alert">${esc(error)}</p>`:''}${notice?`<p class="rewards-notice" role="status">${esc(notice)}</p>`:''}${status==='loading'&&!view?'<div class="rewards-empty" role="status"><p>Finding your current rewards…</p></div>':form==='claim'?claimView():form==='cancel'?cancelView(member):programmeUnavailable?`<div class="rewards-empty"><h2>No loyalty programme here yet.</h2><p>This shop has no programme available to join right now. Your memberships with other merchants are kept separately.</p>${button('Your rewards','all',{style:'primary'})}${button('Find another campus shop','browse')}</div>`:member?memberView(member):view?.programme?programmeView(view.programme):view?listView():`<div class="rewards-empty"><h2>${status==='error'?'Your rewards could not refresh.':'Your merchant rewards, together.'}</h2><p>${status==='error'?'Reconnect and try again. Your existing membership records have not been replaced with sample data.':'Check your current cards, progress and earned rewards.'}</p>${button('Check my rewards','refresh',{style:'primary',disabled:busy||status==='loading'})}</div>`}<p class="rewards-sandbox">Connected test experience · Rewards are merchant programme records. No real bank, MoMo or messaging provider is connected.</p></div></section>`;}
 async function handleClick(element){ensure();const action=typeof element==='string'?element:element?.dataset?.rewardsAction;if(!action)return false;if(action==='signin'){config.onSignIn?.();return true;}if(!signedIn())return false;if(action==='refresh')return refresh();if(action==='recover')return recover();if(busy)return false;if(readOnly()&&['claim','claim-reset','claim-scan','cancel-open','resume','pay','use'].includes(action)){error=readOnlyMessage;notify();return false;}if(action==='member'){selected=limit(element.dataset.membershipId,100);form='';return refresh({membershipId:selected});}if(action==='all'){selected='';context={};form='';view=null;if(config.onAll){config.onAll();return true;}return refresh();}if(action==='browse'){config.onBrowse?.();return true;}if(action==='claim'){if(pending&&!reentry)return false;form='claim';error='';notify();return true;}if(action==='close-form'){form='';claimDraft='';claimProgramme=null;cancelRequest='';error='';notify();return true;}if(action==='claim-reset'){if(pending&&!reentry)return false;claimDraft='';claimProgramme=null;form='claim';error='';notify();return true;}if(action==='claim-scan'){if(pending&&!reentry)return false;try{const value=await config.onScanClaim?.();if(typeof value==='string')return checkClaimCode(value);return true;}catch(failure){error=failure.message||'The linking code could not be scanned.';notify();}return false;}const member=membership();if(!member)return false;if(action==='show-code'){notice='Show your membership card below to the shop team. They confirm the item handover.';notify();config.scrollToCode?.();return true;}if(action==='copy-code'){try{const copy=config.copyText||globalThis.navigator?.clipboard?.writeText?.bind(globalThis.navigator.clipboard);if(typeof copy!=='function')throw Error('Copy unavailable');await copy(member.code);notice='Membership code copied.';}catch{notice='Copy is unavailable. Show the membership code on your card.';}notify();return true;}if(action==='cancel-open'){if(pending)return false;const collection=list(member.collections).find(c=>c.requestId===element.dataset.requestId&&c.state==='held');if(!collection)return false;cancelRequest=collection.requestId;form='cancel';error='';notify();return true;}if(action==='resume'){if(pending)return false;const collection=list(member.collections).find(c=>c.requestId===element.dataset.requestId&&c.state==='held');if(!collection)return false;if(config.canStartPayment?.()===false)return false;const epoch=generation,owner=identity;try{if(typeof config.onResumeCollection!=='function')throw Error('Open the original payment from your saved payments.');const result=await config.onResumeCollection({membership:clone(member),collection:clone(collection)});return current(epoch,owner)&&result!==false;}catch(failure){if(current(epoch,owner)){error=failure.message||'The original payment could not be opened.';notify();}return false;}}if(action==='pay'||action==='use'){if(pending)return false;if(member.active===false){error='This membership is inactive. You can pay the shop normally through Campus Pay, or ask the merchant to review membership.';notify();return false;}const shop=list(member.shops).find(s=>s.id===selectedShop&&s.published===true&&s.accepting===true)||list(member.shops).find(s=>s.published===true&&s.accepting===true);if(!shop){error='No participating shop is currently accepting payments. Refresh or ask the merchant.';notify();return false;}const reward=action==='use'?list(member.rewards).find(r=>r.id===element.dataset.rewardId&&r.type==='discount'&&r.state==='available'&&(!r.expiresAt||Date.parse(r.expiresAt)>(config.now?.()??Date.now()))):null;if(action==='use'&&!reward){error='This reward is no longer available. Refresh your current rewards.';notify();return false;}if(config.canStartPayment?.()===false)return false;const epoch=generation,owner=identity;try{const callback=action==='use'?config.onUseReward:config.onPay;if(typeof callback!=='function')throw Error('Open this shop in Campus Pay to continue.');const result=await callback({membership:clone(member),...(reward?{reward:clone(reward)}:{}),shopId:shop.id});return current(epoch,owner)&&result!==false;}catch(failure){if(current(epoch,owner)){error=failure.message||'This payment could not be opened. Keep any original payment reference.';notify();}return false;}}return false;}
 async function handleSubmit(source){ensure();if(!signedIn()||busy)return false;if(readOnly()){error=readOnlyMessage;notify();return false;}const kind=source?.dataset?.rewardsForm||source?.kind;const values=source?.values||Object.fromEntries(config.formData?config.formData(source):new FormData(source));if(kind==='claim-code')return checkClaimCode(values.claimCode);if(kind==='cancel'){const member=membership();if(!member||!list(member.collections).some(c=>c.requestId===cancelRequest&&c.state==='held')){error='Refresh the original request before cancelling.';notify();return false;}return submitMutation('cancel',{membershipId:member.id,requestId:cancelRequest});}if(!truth(values.membershipConsent)){error=kind==='claim'?'Confirm that you agree to link this membership.':'Read the terms and confirm that you agree to join.';notify();return false;}if(kind==='join'){const program=view?.programme;if(!program?.canJoin||!program.rules||!Number.isInteger(program.ruleVersion)||program.ruleVersion<1||typeof program.consentVersion!=='string'||!program.consentVersion||typeof program.terms!=='string'||!program.terms.trim()||!context.shopId){error='Refresh this shop’s current programme before joining.';notify();return false;}return submitMutation('join',{shopId:context.shopId,ruleVersion:program.ruleVersion,consentVersion:program.consentVersion,membershipConsent:true,marketingConsent:truth(values.marketingConsent)});}if(kind==='claim'){if(!claimDraft||!claimProgramme){error='Check the private linking code and review the existing terms first.';notify();return false;}return submitMutation('claim',{claimCode:claimDraft,ruleVersion:claimProgramme.ruleVersion,consentVersion:claimProgramme.consentVersion,membershipConsent:true,marketingConsent:truth(values.marketingConsent)});}return false;}
 function handleChange(element){ensure();if(element?.name==='rewardsShop'){selectedShop=limit(element.value,100);return true;}return false;}
 function reset(){resetPrivate();identity='';storageOwner='';notify();}
 return {open,refresh,render,handleClick,handleSubmit,handleChange,recover,checkClaimCode,reset,leave(){generation++;sequence++;busy=false;if(status==='loading')status=view?'loaded':'idle';},subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn);},getView(){ensure();return {status,error,notice,busy,selected,context:clone(context),form,pending:pending&&clone(pending),hasPendingMemory:!!pendingMemory,reentry,loyalty:view&&clone(view)};}};
}

const controllers=new WeakMap();
function forContext(ctx){const key=ctx.shared||ctx;let record=controllers.get(key);if(!record){record={ctx,controller:null};const target=()=>record.ctx;record.controller=createConsumerRewards({getUserId:()=>target().shared?.user?.id||'',getIdentity:()=>JSON.stringify([target().connected===true,target().shared?.user?.id||'',target().shared?.authVersion??null,target().shared?.recoveryScope??null,target().shared?.signedIn===true]),isAuthenticated:()=>target().connected===true&&target().shared?.signedIn===true,isReadOnly:()=>target().state?.account?.status==='closed'||target().shared?.account?.status==='closed',api:(...args)=>target().shared.loyalty(...args),onSignIn:()=>target().go({section:'life',page:'account-access'}),onBrowse:()=>target().go({section:'pay',page:'home',hubTab:'campus'}),onAll:()=>target().go({section:'pay',page:'rewards'}),onUseReward:values=>{const callback=target().useLoyaltyReward;if(typeof callback!=='function')throw Error('Open this shop in Campus Pay to continue.');return callback(values);},onPay:values=>{const callback=target().payLoyaltyMerchant;if(typeof callback!=='function')throw Error('Open this shop in Campus Pay to continue.');return callback(values);},onResumeCollection:values=>{const callback=target().resumeLoyaltyCollection;if(typeof callback!=='function')throw Error('Open the original request from your saved payments.');return callback(values);},canStartPayment:()=>target().canStartLoyaltyPayment?.()!==false,onScanClaim:()=>{if(typeof target().scanRewardClaim==='function')return target().scanRewardClaim();target().go({section:'pay',page:'scan',backTo:{section:'pay',page:'rewards'}});},scrollToCode:()=>target().$?.('.rewards-code-panel')?.scrollIntoView?.({block:'start',behavior:'smooth'})});controllers.set(key,record);}record.ctx=ctx;return record.controller;}
export function renderConsumerRewards(ctx,route={}){const controller=forContext(ctx);controller.open(route);return controller.render();}
export function bindConsumerRewards(ctx,route={}){const root=ctx.$?.('[data-consumer-rewards]');if(!root)return()=>{};const controller=forContext(ctx);controller.open(route);let alive=true;const draw=()=>{if(!alive||root.isConnected===false)return;const template=globalThis.document?.createElement?.('template');if(template){template.innerHTML=controller.render();for(const selector of ['.page-head','[data-rewards-content]']){const before=root.querySelector(selector),after=template.content.querySelector(selector);if(before&&after&&before.innerHTML!==after.innerHTML)before.innerHTML=after.innerHTML;}}else root.innerHTML=controller.render();};const unsubscribe=controller.subscribe(draw);const click=event=>{const element=event.target.closest?.('[data-rewards-action]');if(element&&!element.disabled){event.preventDefault?.();void controller.handleClick(element);}};const submit=event=>{if(event.target?.dataset?.rewardsForm){event.preventDefault?.();void controller.handleSubmit(event.target);}};const change=event=>controller.handleChange(event.target);root.addEventListener('click',click);root.addEventListener('submit',submit);root.addEventListener('change',change);const fresh=()=>{const current=controller.getView();if(alive&&root.isConnected!==false&&!current.busy&&current.status!=='loading'&&!['claim','cancel'].includes(current.form))void controller.refresh();};const visible=()=>{if(globalThis.document?.visibilityState!=='hidden')fresh();};globalThis.window?.addEventListener?.('focus',fresh);globalThis.document?.addEventListener?.('visibilitychange',visible);queueMicrotask(fresh);return()=>{alive=false;unsubscribe();root.removeEventListener('click',click);root.removeEventListener('submit',submit);root.removeEventListener('change',change);globalThis.window?.removeEventListener?.('focus',fresh);globalThis.document?.removeEventListener?.('visibilitychange',visible);controller.leave();};}
/** The private linking QR stays in memory, never a URL or payment draft. */
export function openConsumerRewardClaim(ctx,raw){const controller=forContext(ctx);controller.open({});const pending=controller.checkClaimCode(raw);ctx.go({section:'pay',page:'rewards'});return pending;}
export function resetConsumerRewards(ctx){const record=controllers.get(ctx.shared||ctx);record?.controller.reset();controllers.delete(ctx.shared||ctx);}
export const renderRewards=renderConsumerRewards;
export const bindRewards=bindConsumerRewards;
